7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}: LAST3 is
9	 * the upper-cased first three letters of lastName and NNNN is a global 4-digit
10	 * zero-padded sequence equal to one more than the current number of owners (e.g.
11	 * {@code SMI-0007}). Runs after {@link BuildOwner} and before {@link SaveOwner}, so the
12	 * sequence counts existing owners but not the one being created.
13	 */
14	public class AssignCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String lastName = owner.getLastName();
18	        String prefix = (lastName == null ? "" : lastName);
19	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase();
20	        long sequence = ownerRepository.findAll().size() + 1L;
21	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
22	    }
23	}
